  "upgrade.providerConfirmNote": "プランの変更には請求プロバイダーの確認が必要です。料金の差額、日割り計算、発効日は、変更を承認する前に表示される必要があります。アップグレードによって2つ目の同時サブスクリプションが作成されることはありません。",
  "upgrade.chargedThroughProviderNote": "プランの変更は請求プロバイダーを通じて請求されます。サブスクリプションは、現在のプランの下にある「サブスクリプションをキャンセル」ボタンを使ってこのページから、または設定からキャンセルできます。キャンセルすると、有料期間の終了時に今後の更新が停止します。アクセスが即座に終了することはありません。既存の無料ワークスペースは、これらのオプションを表示しただけでは請求されません。",
