  "exports.eyebrow": "データ",
  "exports.title": "エクスポートとバックアップ",
  "exports.subtitleStart": "ダウンロードは常に次に制限されます：",
  "exports.subtitleRest": "。すべてのファイルには、ビジネス名と作成日が表示されます。",
  "exports.createBusinessFirst": "まずビジネスを作成してください — エクスポートはアプリではなくビジネスに属します。",
  "exports.lockedTitle": "CSV および Excel エクスポートは Business の機能です",
  "exports.lockedDesc": "ワークスペースは Essentials プランです。Business では CSV および Excel エクスポート、在庫評価、無制限の商品とスタッフ、仕入先、購買、バンドルが追加されます。",
  "exports.seeBusiness": "Business に含まれる内容を見る",
  "exports.whatTheseAre": "これらのファイルについて",
  "exports.about1": "すべてのデータセットは CSV または実際の Excel ワークブック（.xlsx）として提供されます — 完全な在庫ワークブックは Excel 専用で、データセットごとに1シートです。CSV ファイルは Excel、Numbers、Google Sheets、ほとんどの在庫アプリで開けます。UTF-8 テキスト、引用されたカンマ、メモ内の改行、コードの先行ゼロはすべて保持され、数式のように始まるセルは無効化されるため、スプレッドシートではテキストとして開かれます。",
  "exports.about2": "Excel ファイルでは、SKU、UPC、ISBN、バーコードはテキストセルです — 科学的記数法になることはなく、ゼロが切り取られることもありません。列幅、ヘッダーフィルター、通貨または数量の書式が適用されます。完全な在庫ワークブックでは、商品、在庫レベル、ロケーション、移動が別々のシートに保持されます。",
  "exports.about3": "非常に大きなエクスポートはデータセットごとに20,000行で止まります — その場合、ファイル名にその旨が表示されます（truncated-20000）。そのため、部分的なファイルが完全なものとして扱われることはありません。",
  "exports.about4": "バックアップはデータのスナップショットであり、ワンクリックでの復元ではありません。復元は手動で、まず確認する作業です。そのためファイルを安全に保管してください — アプリ内の何物も、削除されたビジネスをまだ再作成できません。アプリのコードと Base44 プラットフォームのバックアップは、これらのファイルとは別に処理されます。",
  "exports.about5": "写真と添付ファイルは、保存されたリンクとして一覧表示されます — 画像ファイル自体はダウンロードに同梱されません。",
  "exports.backupTitle": "完全なバックアップ",
  "exports.backupDesc": "このビジネスの商品、ロケーション、在庫レベル、完全な移動台帳、仕入先、購買、注文、返品、棚卸し、出品を含む1つのファイルです — さらにそのプロフィール設定も含みます。自分で管理できる場所に保管してください。",
  "exports.backupIncludes1": "商品、コード、原価、メモ",
  "exports.backupIncludes2": "ロケーションとロケーションごとの数量",
  "exports.backupIncludes3": "実行者と時刻を含むすべての移動",
  "exports.backupIncludes4": "購買、注文、返品、棚卸し",
  "exports.buildingBackup": "バックアップを作成中…",
