  "import.eyebrow": "データ",
  "import.title": "インポートセンター",
  "import.subtitleStart": "3つの別々のスプレッドシート操作により、価格修正が在庫入荷として届くことは決してありません。すべては次の中だけに反映されます：",
  "import.subtitleRest": "。そして、ドライランが合格するまで何も書き込まれません。",
