  "import.createDesc": "まだカタログにない行を追加します。すでに使用中の重複した SKU とバーコードはスキップされ、期首在庫は選んだロケーションに領収として入れることができます。",
  "import.updateTitle": "既存の商品を更新する",
  "import.updateDesc": "各行を SKU またはレコード ID で照合し、古い値と提案される新しい値を並べて表示します。空欄のセルは、空欄をクリアするよう求めない限り、保存された値をそのままにします。数量には一切触れません。",
  "import.receiveModeTitle": "在庫を受け取る",
  "import.receiveModeDesc": "到着した数量を1つのロケーションに追加し、すべての行について移動台帳に領収を書き込みます。各バッチには印が付けられるため、同じシートを2回受け取ることはできません。",
  "import.excelNote": "Excel ワークブック（.xlsx）は直接読み取られます — ワークシートを選ぶと、列が自動的に照合されます。コードは完全なまま保持されます：テキストとして保存された UPC は、その数字と先行ゼロを保持します。インポートできない行は理由とともに一覧表示され",
  "import.excelNoteDownload": "、ファイルとしてダウンロードできます。",
