  "print.howBluetoothLead": "Bluetooth。",
  "print.howBluetoothBody": "このページから、デスクトップの Chrome または Edge、および Android Chrome で：ラベルプリンターを選ぶと、ラベルが直接送信されます。iOS Safari では動作しません — iPhone では、Bluetooth 印刷はモバイルアプリとともに提供されます。Zebra ZPL または Brother 独自の言語しか話せないプリンターは、このページが送信するラベルを理解できません。これは、動作すると呼ぶ前に実際のプリンターで確認されます。",
  "print.howWifiLead": "Wi-Fi。",
  "print.howWifiBody": "プリンターをお店の Wi-Fi にインストールし、「印刷」ボタンを使ってください — このコンピューターにインストールされたプリンター経由で、お店のネットワーク越しに印刷されます。iPhone では AirPrint が組み込まれています：同じ Wi-Fi 上の AirPrint プリンターは印刷シートにそのまま表示され、コードもアプリも不要で、アプリに AirPrint 専用コードは不要です。プリンターは AirPrint に対応している必要があり（新しいもののほとんどが対応しています）、スマートフォンとプリンターは同じ Wi-Fi 上にある必要があります。",
  "print.howEthernetLead": "Ethernet。",
  "print.howEthernetBody": "プリンターを Ethernet コードでお店のネットワークに接続し、コンピューターにインストールして、「印刷」ボタンで印刷してください。Ethernet はデスクトップとコンピューター向けの方法です — iPhone は Ethernet コードを使いません。",
  "print.howUsbLead": "USB。",
  "print.howUsbBody": "プリンターをコードでコンピューターに接続し、「印刷」ボタンを使ってください — そこにインストールされたプリンター経由で印刷されます。USB OTG ケーブルを使った Android スマートフォンでは、上記の USB ボタンがプリンターに直接通信します。iPhone は USB 経由で直接印刷できません — WebUSB はありません — そのため Wi-Fi / AirPrint を使うか、モバイルアプリから Bluetooth を使ってください。",
  "print.howCordsLead": "コードは、1ステップ離れて iPhone にも役立ちます。",
  "print.howCordsBody": "お店のコンピューターに接続された USB プリンター、またはネットワークに有線接続された Ethernet プリンターは、お店の Wi-Fi 経由で iPhone に表示されます（AirPrint / 共有プリンター）— コードによってプリンターがネットワークにしっかり接続され、スマートフォンはワイヤレスで届きます。",
  "print.howOfflineLead": "インターネットが切れた場合、",
  "print.howOfflineBody": "このページにすでにあるラベルと文書は引き続き印刷できます — 「印刷」ボタン、ラベル PDF、Bluetooth、USB は接続不要です。インターネットが必要なのは、そもそもページとその商品を読み込むことです。完全なオフラインモード（接続がまったくない状態でアプリで作業すること）は別の大きな開発であり、ここでは主張しません。",
