  "settings.cancelTerms.graceTitle": "有料期間終了後 — 15日間の猶予、その後削除：",
  "settings.cancelTerms.intro": "これらは有料の Luminous StockHaven サブスクリプションの条件です。ウェブサイトのサブスクリプション請求は Stripe を通じて行われます。以下の「サブスクリプションをキャンセル」ボタンを使って、いつでもご自分でサブスクリプションをキャンセルできます — スタッフの承認は不要です。キャンセルと返金のリクエストは、公式のカスタマーサポート連絡先 theluminousbookshop@outlook.com を通じても処理できます。",
  "settings.cancelTerms.noApprovalBody": "いつでもご自分でサブスクリプションをキャンセルできます。スタッフの承認は不要です。今後の更新は、請求プロバイダーがキャンセルを確認した後にのみ停止します。",
  "settings.cancelTerms.noApprovalTitle": "承認なしでキャンセル：",
  "settings.cancelTerms.paymentBody": "有料トライアルの場合、7日間のトライアルには登録時のお支払い方法が必要です。適用されるトライアルのキャンセル期限内にキャンセルしない限り、選択した月額プランはトライアル後に自動的に請求されます。料金、最初の請求日、プロバイダー固有のキャンセル期限は、登録時に表示される必要があります。トライアルの請求は Stripe を通じて行われます。",
  "settings.cancelTerms.paymentTitle": "お支払い方法と自動更新：",
  "settings.cancelTerms.remainingBody": "すでに請求期間分を支払っている場合は、確認済みの支払い済み期限までアクセスを保持できます。早期終了には、適切なプロバイダーの確認と適用される返金処理が必要です。無料トライアルのアクセスは、プロバイダーが確認したトライアル終了日に従って終了します。",
  "settings.cancelTerms.remainingTitle": "残りのアクセス：",
  "settings.cancelTerms.storesBody": "Google Play または Apple App Store を通じて登録したことがある場合は、サブスクリプションはそのストアによって請求・管理されます。登録に使用した同じ Google または Apple アカウントのサブスクリプションセクションで、直接キャンセルする必要がある場合があります。別のウェブサイトのサブスクリプションをキャンセルしたり、このアプリをアンインストールしたり、Luminous StockHaven アカウントの削除をリクエストしたりしても、ストア請求のサブスクリプションが自動的にキャンセルされることはありません。購入時の領収書を確認して、誰が請求しているかをご確認ください。",
  "settings.cancelTerms.storesTitle": "Google Play と Apple App Store のサブスクリプション（ストアを通じて登録した場合）：",
  "settings.cancelTerms.title": "キャンセル条件",
  "settings.cancelTerms.trialBody": "7日間のトライアルは、対象となるお客様ごとに1回だけ使用できます。トライアルやサブスクリプションをキャンセルしても別のトライアルは付与されません。再度のお客様は有料サブスクリプションを選ぶ必要があります。",
  "settings.cancelTerms.trialTitle": "無料トライアルは1回だけ：",
  "settings.canceled.endsOn": "このサブスクリプションはキャンセルされ、{date} に終了します。それまではフルアクセスを維持できます。",
