  "staff.access.noSeatBody": "アカウントにはこのビジネスのスタッフ席がないため、その在庫は閉じたままです。オーナーに「スタッフとロール」で追加してもらってください。",
  "staff.access.noSeatTitle": "このビジネスはあなたのログインに開かれていません",
  "staff.access.pendingBody": "このビジネスには、まだ有効化されていないあなたのメールアドレス宛の招待があります。オーナーにスタッフステータスを有効にしてもらってください。それまではここでは何も見られません。",
  "staff.access.pendingTitle": "招待はまだ有効ではありません",
  "staff.access.signOut": "ログアウト",
  "staff.access.suspendedBody": "管理者が、アクティブなビジネスについてこのスタッフアカウントを停止しました。有効に戻してもらい、再度ログインしてください。",
  "staff.access.suspendedTitle": "アクセスが一時停止されています",
  "staff.addFirst": "最初のスタッフメンバーを追加する",
  "staff.addMember": "スタッフメンバーを追加する",
  "staff.emptyBody": "人を追加し、ロールとそれに伴う権限を与えると、その人はメールで招待され、このビジネスにログインできるようになります。",
  "staff.emptyTitle": "スタッフはまだいません",
  "staff.eyebrow": "チーム",
  "staff.how.p1": "すべてのメンバーにはロールと独自の権限リストがあるため、ロールから始めて、新しいロールを作らずに1つだけ変更できます。ロールを編集しても、すでにそのロールにいるメンバーは書き換えられません — メンバーを開いてロールのデフォルトを再適用してください。",
  "staff.how.p2": "カスタムロールは Business の機能です：Essentials では5つの組み込みロール（オーナー、マネージャー、在庫担当、販売担当、閲覧者）を使います。",
  "staff.how.p3": "招待はメールで送信されます。メンバーは、承諾した後にのみログインできます。このリストから誰かを削除しても、その人のアプリのアカウントは削除されません。",
  "staff.how.p4": "店舗は、その人が割り当てられたロケーションです。それはその人のカードに記録されます。何を開けるかは、依然としてその人のロールと権限で決まります。",
  "staff.how.p5": "権限は、各人が何を開けるかを決めます：ロールの範囲外のメニュー項目は隠され、ブロックされたアドレスではページの代わりに「あなたのロールにはありません」という通知が表示されます。変更は、その人が次にアプリを読み込んだときに適用されます。メンバーを停止すると、その人は完全にロックアウトされます。",
  "staff.how.p6": "管理者はすべてのデータを見て変更でき、アプリのユーザーとロールを管理でき、スタッフロールによって制限されることは決してありません。スタッフ記録のない人 — 新しいビジネスのオーナー — はフルアクセスを保持します。",
  "staff.howTitle": "スタッフとロールの仕組み",
