  "training.warningSentOn": "{date} に警告を送信しました",
  "auth.sameEmailNotice": "すでに Google Play または App Store から私たちのアプリをお持ちですか？こちらでも同じメールアドレスを使ってください — アプリにサインインするもの — そうすれば、店舗と在庫が一緒に移動します。別のメールアドレスでは、まったく新しい空の店舗が始まります。",
  "settings.deleteConfirmWord": "削除",
  "login.cantAccessEmail": "メールにアクセスできませんか？",
  "recovery.title": "アカウントを復旧する",
  "recovery.subtitle": "アカウントのメールアドレスにアクセスできなくなりましたか？予備の鍵で店舗に戻ることができます。",
  "recovery.remembered": "やっぱり思い出しましたか？",
  "recovery.backToLogin": "サインインに戻る",
  "recovery.genericError": "問題が発生しました。もう一度お試しください。",
  "recovery.emailLabel": "あなたのアカウントのメールアドレス",
  "recovery.backupCodeLabel": "バックアップコードの1つ",
  "recovery.backupCodeHint": "設定 → セキュリティから保存した1回限りのコードです。各コードは正確に1回だけ使えます。",
  "recovery.useBackupCode": "バックアップコードを使う",
  "recovery.orDivider": "または",
  "recovery.emailMeCode": "予備のメールアドレスにコードをメールする",
  "recovery.emailMeCodeHint": "予備のメールアドレスを設定している場合、6桁のコードをそこに送信します。アカウントを守るため、このページは常に同じように答えます — コードが送信されたかどうかは分かりません。",
  "recovery.codeSent": "予備のメールアドレスが登録されている場合、6桁のコードが今そちらに向かっています。10分で有効期限が切れます。",
  "recovery.codeLabel": "6桁のコード",
  "recovery.verifyCode": "コードを確認する",
  "recovery.startOver": "最初からやり直す",
  "recovery.changeIntro": "入りました — ただし1ステップだけです：アカウントの新しいメールアドレスを選んでください。店舗、在庫、チームへのアクセスはすべて一緒に移動します。",
  "recovery.doneBody": "あなたのアカウントのメールアドレスが変更され、このサインインは通常のサインインに戻りました。お帰りなさい。",
  "recovery.doneButton": "私の店舗へ進む",
  "settings.security.title": "セキュリティと予備の鍵",
  "settings.security.description": "予備の鍵は、必要になる前に設定してください：アカウントのメールアドレスにアクセスできなくなった場合、それが店舗を取り戻す方法です。",
  "settings.security.genericError": "問題が発生しました。もう一度お試しください。",
  "settings.security.accountEmail": "アカウントのメールアドレス",
  "settings.security.backupCodesTitle": "バックアップコード",
  "settings.security.backupCodesDesc": "1回限りの予備の鍵です。印刷するか書き留めて、安全な場所に保管してください — メールを失った場合、各コードで1回だけ戻ることができます。",
  "settings.security.codesRemaining": "未使用のバックアップコードの残り：{count}",
