  "settings.security.printCodes": "これらのコードを印刷する",
  "settings.security.backupEmailTitle": "予備のメールアドレス",
  "settings.security.backupEmailDesc": "あなたが管理する2つ目のメールアドレスです。メインのメールアドレスに届かなくなった場合、代わりにここへ復旧コードを送信できます。",
  "settings.security.backupEmailLabel": "予備のメールアドレス",
  "settings.security.backupEmailSave": "確認コードを送信する",
  "settings.security.backupEmailPending": "そのアドレスに6桁のコードを送信しました。ここに入力すると、予備のメールアドレスとしての設定が完了します。",
  "settings.security.backupEmailVerified": "予備のメールアドレスを確認しました：{email}",
