  "workforce.tab.rewards": "報酬",
  "training.lessons.mgr-give-rewards.step1": "ワークフォースを開いて報酬をタップしてください。チームメンバーを選び、次に種類を選んでください：店舗での割引、ギフトカード、または自分の言葉で説明するその他です。",
  "training.lessons.mgr-give-rewards.step2": "報酬に短い名前を付け、希望すればメモも付けてください。その人にベルがすぐに届き、報酬は独自のコードとともに「私の報酬」で待機します。",
  "training.lessons.mgr-give-rewards.step3": "設計上の境界：あなたが報酬を与えられるのはスタッフだけです。自分自身や別のマネージャーに報酬を与えることはできません — マネージャーへの報酬はオーナーの判断であり、アプリははっきりと拒否します。",
  "training.lessons.mgr-give-rewards.step4": "レジでは、チームメンバーが見せるコードを入力して使用済みにしてください — 各コードは1回だけ使えます。計画が変わった場合は、自分が与えた報酬を無効にできます。オーナーの贈り物を無効にするのはオーナーです。",
  "training.lessons.mgr-give-rewards.title": "スタッフに報酬を与える",
  "training.lessons.owner-give-rewards.step1": "報酬はワークフォースの報酬タブの中にあり、Business プラン専用です — Essentials では、そのタブにはロックされた扉が表示され、チームはより大きなプランに何があるかを見ることができます。",
  "training.lessons.owner-give-rewards.step2": "チームの誰にでも報酬を与えることができます — スタッフもマネージャーもです。人を選んで、次に種類を選んでください：店舗での割引（選んだ任意の割合）、どこでも使えるギフトカード、または自分の言葉で説明する任意の特典です。",
  "training.lessons.owner-give-rewards.step3": "報酬は独自の1回限りのコードとともに届き、その人のベルを鳴らします。その人がレジでコードを見せ、オーナーまたはマネージャーが入力して使用済みにします。",
  "training.lessons.owner-give-rewards.step4": "印刷または共有される報酬の伝票には、あなたのビジネスの名前だけが入ります — アプリの名前は決して入りません。それはあなたの店舗の感謝であり、広告ではありません。",
  "training.lessons.owner-give-rewards.title": "報酬を与える（Business プラン）",
  "training.lessons.owner-rewards-oversight.step1": "あなたのマネージャーも報酬を与えることができます — スタッフだけにです。マネージャーが自分自身や別のマネージャーに報酬を与えることはアプリが拒否します。マネージャーへの報酬は常にあなたの判断です。",
  "training.lessons.owner-rewards-oversight.step2": "ビジネス内のすべての報酬が報酬の履歴で見えます：誰が与えたか、誰が受け取ったか、使用可能か、使用済みか、無効かです。マネージャーが見えるのは、自分が与えた報酬と受け取った報酬だけです。",
  "training.lessons.owner-rewards-oversight.step3": "マネージャーが与えたものも含め、どの報酬も無効にできます。マネージャーは自分の贈り物を無効にできますが、あなたのものは決してできません。",
  "training.lessons.owner-rewards-oversight.step4": "各コードは正確に1回だけ使え、無効にされた報酬は決して使えません — 履歴には、報酬がどのように終わったかが常に表示されます。",
  "training.lessons.owner-rewards-oversight.title": "報酬を見守る：マネージャーの付与",
  "training.lessons.staff-your-rewards.step1": "マネージャーまたはオーナーがあなたに報酬を与えると、ベルが鳴ります。ワークフォースを開いて報酬をタップすると、「私の報酬」の下に表示されます。",
  "training.lessons.staff-your-rewards.step2": "すべての報酬には独自のコードがあります。自分だけのものにしてください — レジでコードを見せた人が、その報酬を使う人です。",
  "training.lessons.staff-your-rewards.step3": "使うには、購入時にコードを見せてください。レジの人が入力して使用済みにします — 各コードは正確に1回だけ使えます。",
  "training.lessons.staff-your-rewards.step4": "報酬は Business プランの特典です。あなたの店舗が Business でない場合、報酬タブには代わりにロックされた扉が表示されます — それはプランによるもので、間違いではありません。",
  "training.lessons.staff-your-rewards.title": "あなたの報酬：コードの見つけ方と使い方",
  "training.module.rewards": "報酬と特典",
